  private pendingDomainIds=new Set<string>();
  private domainListener?: (event:{workspace:string;entities:Array<{id:string;kind:string}>})=>void;
  onDomainChanged(listener:(event:{workspace:string;entities:Array<{id:string;kind:string}>})=>void){this.domainListener=listener;}
