  private txLevel=0;
  private initializing=true;
  private restoreAuthorityDirty=false;
  db: {exec:(sql:string)=>void;pragma:(sql:string)=>void;prepare:(sql:string)=>any;backup:(destination:string)=>Promise<void>;close:()=>void};
  root: string;
  private databasePath:string;
  private backupKeyPath:string;
  private lockPath='';
  private lockNonce:string=crypto.randomUUID();
  private takeWorkspaceLock(preclaimed=false){this.lockPath=path.join(this.root,'.atelier.lock');if(preclaimed){const stat=fs.lstatSync(this.lockPath);if(!stat.isFile()||stat.isSymbolicLink()||JSON.parse(fs.readFileSync(this.lockPath,'utf8')).nonce!==this.lockNonce)throw new Error('Workspace activation lock ownership changed.');return;}for(let attempt=0;attempt<2;attempt++){try{const fd=fs.openSync(this.lockPath,'wx',0o600);fs.writeFileSync(fd,JSON.stringify({pid:process.pid,nonce:this.lockNonce,createdAt:new Date().toISOString()}));fs.closeSync(fd);return;}catch(error){if((error as NodeJS.ErrnoException).code!=='EEXIST')throw error;let stale=false;try{const stat=fs.lstatSync(this.lockPath);if(!stat.isFile()||stat.isSymbolicLink())throw new Error('Workspace lock path is unsafe.');const owner=JSON.parse(fs.readFileSync(this.lockPath,'utf8')),pid=Number(owner.pid);if(!Number.isInteger(pid)||pid<1)stale=true;else try{process.kill(pid,0);}catch(problem){if((problem as NodeJS.ErrnoException).code==='ESRCH')stale=true;else throw problem;}}catch(problem){if((problem as NodeJS.ErrnoException).code==='ENOENT')stale=true;else throw problem;}if(!stale||attempt>0)throw new Error('Workspace is locked by another Atelier process.');fs.rmSync(this.lockPath,{force:true});}}throw new Error('Could not acquire the Atelier workspace lock.');}
