    if(!project)this.put({kind:'project',name:'My Unity Project',data:{unityPath:'',description:'Your project workspace'}});
    const resourceRoot=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');const bundledBlender=typeof app?.getAppPath==='function'?path.join(resourceRoot,'tools','blender-5.2.2-windows-x64','blender.exe'):'';
    const activeProject=project||this.db.prepare("SELECT id FROM entities WHERE kind='project' LIMIT 1").get() as {id:string}|undefined;
    const defaults:AppSettings={theme:'dark',motion:'full',workspace:root,unityPath:'',codexPath:'codex',nodePath:this.findInstalledNode(),blenderPath:fs.existsSync(bundledBlender)?bundledBlender:'',activeProjectId:activeProject?.id||null,locale:'en',soundEnabled:true,soundVolume:.28,autoCheckUpdates:true};
    this.db.prepare('INSERT OR IGNORE INTO settings(key,value) VALUES(?,?)').run('app',JSON.stringify(defaults));
